// Port of shell-completions' Clink generator: a Lua argmatcher for `cmd.exe` through Clink, chained
// `:addarg` / `:addflags` / `:adddescriptions` per command.
package rtok.completions

internal object ClinkScript {
    private const val INDENT = 4
    private const val BASE = 2

    fun render(root: CompNode): String =
        "-- Clink completions for ${root.name}, generated by `${root.name} completions clink`.\n" +
            "-- Put this file in a Clink script directory (`clink info` lists them).\n" +
            matcher(root, "clink.argmatcher(${lua(root.name)})", 0) + "\n"

    private fun matcher(
        n: CompNode,
        head: String,
        depth: Int,
    ): String {
        val pad = " ".repeat(INDENT * depth + BASE)
        val out = StringBuilder(head)
        val descriptions = mutableListOf<String>()
        if (n.children.isEmpty()) {
            n.positionals.forEach { out.append("\n$pad:addarg({})") }
        } else {
            val items =
                n.children.map { c ->
                    descriptions += "[${lua(c.name)}] = ${lua(c.about)}"
                    "${lua(c.name)} .. ${matcher(c, "clink.argmatcher()", depth + 1)}"
                }
            out.append("\n$pad:addarg({\n$pad  ${items.joinToString(",\n$pad  ")}\n$pad})")
        }
        val flags = mutableListOf<String>()
        for (o in n.opts) {
            for (name in o.names) {
                flags += if (o.takes) "${lua(name)} .. clink.argmatcher():addarg(${if (o.path) "clink.filematches" else "{}"})" else lua(name)
                descriptions += "[${lua(name)}] = ${lua(o.help)}"
            }
        }
        if (flags.isNotEmpty()) out.append("\n$pad:addflags({ ${flags.joinToString(", ")} })")
        if (descriptions.isNotEmpty()) out.append("\n$pad:adddescriptions({ ${descriptions.joinToString(", ")} })")
        return out.toString()
    }

    /** A Lua string literal: `\`, `"` escaped, newlines and tabs folded to spaces, other controls dropped. */
    fun lua(s: String): String =
        buildString {
            append('"')
            for (c in s) {
                when {
                    c == '\\' -> append("\\\\")
                    c == '"' -> append("\\\"")
                    c == '\n' || c == '\r' || c == '\t' -> append(' ')
                    c.isISOControl() -> Unit
                    else -> append(c)
                }
            }
            append('"')
        }
}
